/*
 * Multi-Sensor Weather Station with Air Quality
 *
 * Wiring:
 *   BME280:  VCC->5V  GND->GND  SCL->A5  SDA->A4
 *   DHT11:   VCC->5V  GND->GND  DAT->D2
 *   LDR:     VCC->5V  GND->GND  AO->A1
 *   MQ-2:    VCC->5V  GND->GND  A0->A0
 *   LCD 20x4: VCC->5V  GND->GND  SCL->A5  SDA->A4
 *
 * Drag the sliders on each sensor to simulate conditions.
 */

#include <Wire.h>
#include <SimpleBME280.h>
#include <LiquidCrystal_I2C.h>

SimpleBME280 bme;
LiquidCrystal_I2C lcd(0x27, 20, 4);

const int gasPin = A0;
const int ldrPin = A1;
const int dhtPin = 2;

int readDHTTemp() {
  float v = sensorValue('dht11', 'temperature');
  if (v >= 0) return (int)v;
  return 25;
}

int readDHTHum() {
  float v = sensorValue('dht11', 'humidity');
  if (v >= 0) return (int)v;
  return 60;
}

void setup() {
  Serial.begin(115200);
  Wire.begin();
  bme.begin();
  lcd.init();
  lcd.backlight();
  lcd.setCursor(0, 0);
  lcd.print("Multi Weather Station");
  lcd.setCursor(0, 1);
  lcd.print("Initializing...");
  delay(1500);
  lcd.clear();
  Serial.println("Multi-Sensor Weather Station + Air Quality");
  Serial.println("==========================================");
}

void loop() {
  float bmeTemp  = bme.readTemperature();
  float bmeHum   = bme.readHumidity();
  float bmePres  = bme.readPressure();
  int dhtTemp    = readDHTTemp();
  int dhtHum     = readDHTHum();
  int lightLevel = analogRead(ldrPin);
  int gasRaw     = analogRead(gasPin);

  Serial.print("BME Temp:  "); Serial.print(bmeTemp, 1); Serial.println(" C");
  Serial.print("BME Hum:   "); Serial.print(bmeHum, 1); Serial.println(" %");
  Serial.print("BME Pres:  "); Serial.print(bmePres / 100.0, 1); Serial.println(" hPa");
  Serial.print("DHT Temp:  "); Serial.print(dhtTemp); Serial.println(" C");
  Serial.print("DHT Hum:   "); Serial.print(dhtHum); Serial.println(" %");
  Serial.print("Light:     "); Serial.print(lightLevel); Serial.println(" lx");
  Serial.print("Air Qual:  "); Serial.print(gasRaw);
  if (gasRaw < 200) Serial.println(" (Good)");
  else if (gasRaw < 400) Serial.println(" (Moderate)");
  else if (gasRaw < 600) Serial.println(" (Poor)");
  else Serial.println(" (Hazardous)");
  Serial.println("==========================================");

  // LCD Line 1: BME280 Temperature & Humidity
  lcd.setCursor(0, 0);
  lcd.print("T:");
  lcd.print(bmeTemp, 1);
  lcd.print((char)223);
  lcd.print("C H:");
  lcd.print((int)bmeHum);
  lcd.print("%     ");

  // LCD Line 2: Pressure & Light
  lcd.setCursor(0, 1);
  lcd.print("P:");
  lcd.print((int)(bmePres / 100.0));
  lcd.print("hPa L:");
  lcd.print(lightLevel);
  lcd.print("    ");

  // LCD Line 3: DHT11 readings
  lcd.setCursor(0, 2);
  lcd.print("DHT:");
  lcd.print(dhtTemp);
  lcd.print((char)223);
  lcd.print("C ");
  lcd.print(dhtHum);
  lcd.print("%    ");

  // LCD Line 4: Air Quality
  lcd.setCursor(0, 3);
  lcd.print("Air:");
  lcd.print(gasRaw);
  lcd.print(" ");
  if (gasRaw < 200) lcd.print("[GOOD]     ");
  else if (gasRaw < 400) lcd.print("[MODERATE] ");
  else if (gasRaw < 600) lcd.print("[POOR]     ");
  else lcd.print("[HAZARDOUS]");

  delay(2000);
}
